# flake8: noqa

import collections
import copy
import multiprocessing
import re
import random
import select
import socket
import threading
import time
import traceback

import ta_emss.utilities.xterm_lib.asncoder as asncoder
import ta_emss.utilities.xterm_lib.message_def as message_def
import ta_emss.utilities.xterm_lib.xsocket as xsocket
from ta_emss.utilities.xterm_lib.timer import Timer
from ta_emss.utilities.xterm_lib.flogger import Flogger
from ta_emss.utilities.xterm_lib.defs import *

g_debug = False
g_enable_prints = True

MAX_PENDING_TASKS = 20


class GNBConn(threading.Thread):
    def __init__(
        self,
        gnb_config,
        local_ip,
        farend_ip=None,
        client=None,
        xnap_config=None,
        logger=None,
        parent_sch=None,
        log_screen=True,
        log_file=True,
        asn_coder=None,
    ):
        super(GNBConn, self).__init__()
        self.local_ip = local_ip

        self.farend_ip = farend_ip
        self.client = client
        self.socket = None
        self.asn_coder = asn_coder

        self.xnap_config = xnap_config if xnap_config is not None else {}

        self.port = 38422
        self.new_gnb_config = copy.deepcopy(gnb_config)
        self.gnb_config = copy.deepcopy(gnb_config)
        self.running = False
        self.logger = logger
        self.log_screen = log_screen
        self.log_file = log_file
        self.parent_sch = parent_sch
        self.num_msg_rx = 0
        self.num_msg_tx = 0
        self.errors = 0
        self.hb = 0
        self.gnb_id = self.gnb_config["GNB_ID"]
        self.mcc = self.gnb_config["MCC"]
        self.mnc = self.gnb_config["MNC"]
        self.arfcn = self.gnb_config["ARFCN"]
        self.link_state = None  # "INIT", "CONNECTED", "CLOSED"
        self.link_substate = (
            None  # "NONE", "SETUP_REQUEST", "CONFIG_UPDATE", "CONFIG_UPDATE_FAILURE"
        )
        self.tasks = collections.deque()
        self.task_map = {
            TSK_XN_SETUP: self.setup_link,
            TSK_GNB_CONFIGURATION_UPDATE: self.send_update,
            TSK_CFG_INC_PCI: self.cfg_inc_pci,
            TSK_CFG_INC_TAC: self.cfg_inc_tac,
            TSK_CFG_INC_GNB_ID: self.cfg_inc_gnb_id,
            TSK_CFG_INC_MCC: self.cfg_inc_mcc,
            TSK_CFG_INC_MNC: self.cfg_inc_mnc,
            TSK_CFG_INC_EARFCN: self.cfg_inc_earfcn,
            TSK_CFG_INC_CELL_ID: self.cfg_inc_cell_id,
        }
        self.timers = {
            TMR_XN_SETUP: Timer(
                self.xnap_config["SETUP_PERIOD"],
                callback=self.setup_link,
                retries=(
                    self.xnap_config["SETUP_RETRIES"]
                    if "SETUP_RETRIES" in self.xnap_config
                    else 3
                ),
            )
            if "SETUP_PERIOD" in self.xnap_config
            else None,
        }
        self.full_msg = ""

    def is_timer_running(self, tname):
        ret = False
        if tname in self.timers and self.timers[tname] is not None:
            ret = self.timers[tname].is_running()
        return ret

    def start_timer(self, tname):
        if tname in self.timers and self.timers[tname] is not None:
            self.timers[tname].start()

    def stop_timer(self, tname):
        if tname in self.timers and self.timers[tname] is not None:
            self.timers[tname].stop()

    def check_timers(self):
        ret = True
        for tname in self.timers.keys():
            if (
                self.timers[tname] is not None
                and self.timers[tname].is_running()
                and self.timers[tname].check_expired()
            ):
                if g_debug: self.log("Timer {} expired.".format(tname))
                ret = False
        return ret

    def get_num_pending_tasks(self):
        return len(self.tasks)

    def put_task(self, task):
        num_pending = self.get_num_pending_tasks()
        if g_debug: self.log("Inserting task={} (pending={}).".format(task, num_pending))
        self.tasks.append(task)

    def process_task(self):
        num_pending = self.get_num_pending_tasks()
        for i in range(num_pending):
            task = self.tasks.popleft()
            if g_debug: self.log("Processing task={} (pending={}).".format(task, num_pending))
            if task in self.task_map:
                self.task_map[task]()
            else:
                self.log("WARNING: process_task: Task not defined: {}".format(task))

    def get_gnb_config(self):
        return {"OLD": self.gnb_config, "NEW": self.new_gnb_config}

    def cfg_inc_pci(self):
        for i, cell in enumerate(self.new_gnb_config["SERVED_CELLS"]):
            pci_max = (
                self.new_gnb_config["PCI_MAX"]
                if "PCI_MAX" in self.new_gnb_config
                else 503
            )
            cell["PCI"] += 3
            if cell["PCI"] >= pci_max + 1:
                cell["PCI"] -= pci_max + 1

    def cfg_inc_cell_id(self):
        for i, cell in enumerate(self.new_gnb_config["SERVED_CELLS"]):
            cell["CELL_ID"] += 1
            if cell["CELL_ID"] >= 256:
                cell["CELL_ID"] -= 256

    def cfg_inc_tac(self):
        self.new_gnb_config["TAC"] += 1
        if self.new_gnb_config["TAC"] > 65535:
            self.new_gnb_config["TAC"] = 1

    def cfg_inc_gnb_id(self):
        self.new_gnb_config["GNB_ID"] += 1000
        if self.new_gnb_config["GNB_ID"] > 1048575:
            self.new_gnb_config["GNB_ID"] = self.gnb_id

    def cfg_inc_mcc(self):
        mcc = int(self.new_gnb_config["MCC"])
        mcc += 1
        if mcc > 999:
            mcc = self.mcc
        self.new_gnb_config["MCC"] = "{:03d}".format(mcc)

    def cfg_inc_mnc(self):
        mnc = int(self.new_gnb_config["MNC"])
        mnc += 10
        if mnc > 999:
            mnc = self.mnc

        if mnc <= 99:
            self.new_gnb_config["MNC"] = "{:02d}".format(mnc)
        else:
            self.new_gnb_config["MNC"] = "{:03d}".format(mnc)

    def cfg_inc_earfcn(self):
        self.new_gnb_config["ARFCN"] += 10
        if self.new_gnb_config["ARFCN"] > 65535:
            self.new_gnb_config["ARFCN"] = self.arfcn

    def open_client_socket(self):
        try:
            if g_debug: self.log("Creating XNAP Client SCTP socket...")
            self.socket = xsocket.get_sctp_socket(self.local_ip)
            if g_debug: self.log("Binding XNAP Client SCTP socket to local ip addr={}.".format(self.local_ip))
            self.socket.bind((self.local_ip, self.port))
            if g_debug: self.log("Connecting XNAP Client to farend ip addr={}.".format(self.farend_ip))
            xsocket.connect(self.socket, self.farend_ip, self.port)
            if g_enable_prints: self.log("XNAP Client connected {}.".format(self.local_ip))
        except socket.error as err:
            self.logerror("Could not open xnap client socket: {}.".format(err))
            self.socket.close()
            self.socket = None
        except Exception as ex:
            self.logerror("Exception-open_client_socket[{}]".format(ex))
            self.socket = None

    def close_client_socket(self):
        if self.socket:
            self.socket.shutdown(socket.SHUT_RDWR)
            self.socket.close()
        self.socket = None

    def desc(self):
        return "[{}] (hb:{}, rx:{}, tx:{}, err:{}, state:{}, substate:{}, local={}, far={}, tasks={})".format(
            self.gnb_id,
            self.hb,
            self.num_msg_rx,
            self.num_msg_tx,
            self.errors,
            self.link_state,
            self.link_substate,
            self.local_ip,
            self.farend_ip,
            len(self.tasks),
        )

    def send_msg(self, msg_hex, msg_desc):
        if not self.socket:
            self.logerror(
                "Cannot send message {} - no client connected.".format(msg_desc)
            )
            return 0
        try:
            if g_enable_prints: self.log("<--- Sending XNAP {}".format(msg_desc))
            if g_debug: self.logfile("[{}]".format(msg_hex))
            xsocket.send(self.socket, bytes.fromhex(msg_hex))
            self.num_msg_tx += 1
        except Exception as exc:
            self.logerror("Unable to send XNAP {} ({}).".format(msg_desc, exc))
            return 0
        return 1

    def is_link_ready(self):
        return self.link_state == LS_CONNECTED and self.link_substate == LSS_NONE

    def setup_link(self):
        if self.is_link_ready():
            return

        if self.is_timer_running(TMR_XN_SETUP):
            return

        msg_desc = "XnSetupRequest with PCIs="
        for i, cell in enumerate(self.gnb_config["SERVED_CELLS"]):
            msg_desc += "c{}({})".format(i + 1, cell["PCI"])

        msg_str = message_def.XnSetupRequest(self.gnb_config)
        msg_hex = self.asn_coder.encode_asn(msg_str)
        if msg_hex.find("ERROR:") != -1:
            self.logerror("Encoding failure.")
            self.logfile(msg_str)
        elif self.send_msg(msg_hex, msg_desc):
            self.change_state(lss=LSS_SETUP_REQUEST)
            self.start_timer(TMR_XN_SETUP)

    def send_update(self):
        if not self.is_link_ready():
            return

        if self.is_timer_running(TMR_GNB_CONFIGURATION_UPDATE):
            return

        if g_enable_prints: self.print_gnb_config_diff(self.gnb_config, self.new_gnb_config)

        msg_str = message_def.NGRANNodeConfigurationUpdate(
            self.gnb_config, self.new_gnb_config
        )
        self.gnb_config = copy.deepcopy(self.new_gnb_config)
        msg_hex = self.asn_coder.encode_asn(msg_str)
        if msg_hex.find("ERROR:") != -1:
            self.logerror("Encoding failure.")
            self.logfile(msg_str)
        elif self.send_msg(msg_hex, "NGRANNodeConfigurationUpdate"):
            self.change_state(lss=LSS_CONFIG_UPDATE)
            self.start_timer(TMR_GNB_CONFIGURATION_UPDATE)

    def print_gnb_config_diff(self, gnb_config, new_gnb_config):
        msg = "XN_CFG_UPD: "
        if gnb_config["MCC"] != new_gnb_config["MCC"]:
            msg += "mcc({} -> {}) ".format(gnb_config["MCC"], new_gnb_config["MCC"])
        if gnb_config["MNC"] != new_gnb_config["MNC"]:
            msg += "mnc({} -> {}) ".format(gnb_config["MNC"], new_gnb_config["MNC"])
        if gnb_config["GNB_ID"] != new_gnb_config["GNB_ID"]:
            msg += "gnb_id({} -> {}) ".format(
                gnb_config["GNB_ID"], new_gnb_config["GNB_ID"]
            )
        if gnb_config["TAC"] != new_gnb_config["TAC"]:
            msg += "tac({} -> {}) ".format(gnb_config["TAC"], new_gnb_config["TAC"])
        if gnb_config["ARFCN"] != new_gnb_config["ARFCN"]:
            msg += "earfcn({} -> {}) ".format(
                gnb_config["ARFCN"], new_gnb_config["ARFCN"]
            )
        for i, cell in enumerate(gnb_config["SERVED_CELLS"]):
            try:
                new_cell = new_gnb_config["SERVED_CELLS"][i]
            except IndexError:
                msg += "DEL(s{}) ".format(i)
                continue
            if cell["PCI"] != new_cell["PCI"]:
                msg += "s{}-pci({} -> {}) ".format(i, cell["PCI"], new_cell["PCI"])
            if cell["CELL_ID"] != new_cell["CELL_ID"]:
                msg += "s{}-cell_id({} -> {}) ".format(
                    i, cell["CELL_ID"], new_cell["CELL_ID"]
                )
        self.log(msg)

    def change_state(self, ls=None, lss=None):
        prev_ls = self.link_state
        prev_lss = self.link_substate

        if ls is not None:
            self.link_state = ls
        if lss is not None:
            self.link_substate = lss

        if (ls is not None) and (ls != prev_ls):
            self.logfile(
                "=== SCE: LS({} -> {}), LSS({} -> {}).".format(
                    prev_ls, self.link_state, prev_lss, self.link_substate
                )
            )
            self.parent_sch.update_status(req=True)

    def preprocess_msg(self):
        msg = self.asn_coder.decode_asn(self.full_msg)
        # self.log(f"### DECODER OUTPUT=[{msg}]")
        srch = re.search(r'!!! error: decoded (\d+) bytes, out of (\d+) \((\d+) left\)', msg)
        if srch:
            num_decoded = int(srch.group(1))
            num_total = int(srch.group(2))
            num_left = int(srch.group(3))
            self.log(f"Message glued: first message size={num_decoded}, total={num_total}, left={num_left}")
            data_to_process = self.full_msg[0:num_decoded*2]
            self.full_msg = self.full_msg[num_decoded*2:]
            self.log(f"### Data to process: {data_to_process}")
            self.log(f"### Data left: {self.full_msg}")
            msg = self.asn_coder.decode_asn(data_to_process)
            self.process_msg(msg)
        elif msg.find("End of input reached before message was fully decoded") != -1:
            curr_size = int(len(self.full_msg) / 2)
            self.log(f"Message not fully received: current size={curr_size}")
        elif msg.find("Output buffer too small") != -1:
            curr_size = int(len(self.full_msg) / 2)
            self.logerror(f"Output buffer too small for decoder: current size={curr_size}")
            self.full_msg = ""
        else:
            self.process_msg(msg)
            self.full_msg = ""

    def process_msg(self, msg):
        recv_msg = "---> Received XNAP "
        self.num_msg_rx += 1

        if msg.find("!!! error:") != -1:
            self.logerror("ASN decoding failed.")
            self.log(msg)
            self.change_state(ls=LS_INIT, lss=LSS_NONE)

        elif msg.find("NGRANNodeConfigurationUpdateAcknowledge") != -1:
            if g_enable_prints: self.log(recv_msg + "NGRANNodeConfigurationUpdateAcknowledge")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_GNB_CONFIGURATION_UPDATE)

        elif msg.find("NGRANNodeConfigurationUpdateFailure") != -1:
            self.log(recv_msg + "NGRANNodeConfigurationUpdateFailure")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_GNB_CONFIGURATION_UPDATE)
            self.handle_time_to_wait(msg, TMR_GNB_CONFIGURATION_UPDATE, self.send_update)

        elif msg.find("NGRANNodeConfigurationUpdate") != -1:
            self.log(recv_msg + "NGRANNodeConfigurationUpdate")
            self.change_state(ls=LS_CONNECTED)
            msg_str = message_def.NGRANNodeConfigurationUpdateAcknowledge()
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, "NGRANNodeConfigurationUpdateAcknowledge"):
                self.change_state(lss=LSS_NONE)

        elif msg.find("XnSetupResponse") != -1:
            if g_enable_prints: self.log(recv_msg + "XnSetupResponse")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_XN_SETUP)

        elif msg.find("XnSetupFailure") != -1:
            self.log(recv_msg + "XnSetupFailure")
            self.change_state(ls=LS_CONNECTED, lss=LSS_SETUP_FAILURE)
            self.handle_time_to_wait(msg, TMR_XN_SETUP, self.setup_link)

        elif msg.find("XnSetupRequest") != -1:
            msg_desc = "XnSetupResponse with PCIs="
            for i, cell in enumerate(self.gnb_config["SERVED_CELLS"]):
                msg_desc += "c{}({})".format(i + 1, cell["PCI"])

            self.log(recv_msg + "XnSetupRequest")
            msg_str = message_def.XnSetupResponse(self.gnb_config)
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, msg_desc):
                self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)

        elif msg.find("ResetRequest") != -1:
            self.log(recv_msg + "ResetRequest")
            msg_str = message_def.ResetResponse()
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, "ResetResponse"):
                self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)

        else:
            self.log(recv_msg + "Unknown")
            self.log(msg)

    def handle_time_to_wait(self, msg, timer_name, timer_callback):
        ttw = self.asn_coder.extract_time_to_wait(msg)
        if ttw:
            if timer_name in self.timers:
                self.timers[timer_name].stop()
            new_timer = Timer(ttw, callback=timer_callback)
            self.timers[timer_name] = new_timer
            self.timers[timer_name].start()
            if g_enable_prints: self.log("Started TimeToWait timer {}: {} [s]".format(timer_name, ttw))

    def run(self):
        try:
            self.change_state(ls=LS_INIT, lss=LSS_NONE)

            if self.client is None:
                self.open_client_socket()
            else:
                self.socket = self.client[0]
                self.farend_ip = self.client[1][0]

            self.running = True
            while self.running:
                self.hb += 1
                # self.log(" hb={}, ls={}, lss={}".format(self.hb, self.link_state, self.link_substate))

                if self.errors:
                    self.log("Errors exist. Closing connection...")
                    break

                self.process_task()
                if not self.check_data():
                    break

                self.check_timers()

            self.close_client_socket()
            if g_enable_prints: self.log("XNAP Client disconnected {}...".format(self.local_ip))
            self.change_state(ls=LS_CLOSED, lss=LSS_NONE)
        except Exception as exc:
            self.log(f"Exception: {exc}")
            self.log(traceback.format_exc())
        self.running = False

    def check_data(self):
        if self.socket is None:
            return False

        inputs = [self.socket]
        select_timeout = 1
        ret = True
        try:
            inputready, outputready, exceptready = select.select(
                inputs, [], [], select_timeout
            )
            if len(inputready):
                try:
                    data = xsocket.recv(self.socket)
                    if data:
                        self.logfile(
                            "XNAP Client Data received from {}, len={}.".format(
                                self.local_ip, len(data)
                            )
                        )
                        data = data.hex().upper()
                        if g_debug: self.logfile("[{}]".format(data))
                        self.full_msg += data
                        self.preprocess_msg()
                    else:
                        self.logerror("XNAP Farend connection closed.")
                        ret = False
                except socket.timeout:
                    self.logerror("XNAP Client Socket timeout")
                    ret = False
                except socket.error as err:
                    self.logerror("XNAP Client Socket error:{}".format(err))
                    ret = False
            elif self.full_msg:
                self.preprocess_msg()
        except select.error as err:
            self.logerror("XNAP Client Data select error: {}.".format(err))
            ret = False
        return ret

    def is_running(self):
        return self.running

    def stop(self):
        self.running = False

    def loginf(self):
        return "[" + str(self.gnb_id) + "-" + str(self.farend_ip) + "] "

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.log_screen:
            print(msg_out)

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        return msg_out

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.errors += 1


class SchedulerXn(multiprocessing.Process):
    def __init__(self, id, mdict, gnbs, db, mp_pipe, mp_lock):
        super(SchedulerXn, self).__init__()
        self.id = id
        self.mdict = mdict
        self.db = db
        self.mp_pipe = mp_pipe
        self.mp_lock = mp_lock
        self.gnbs = []
        self.port = 38422
        self.logger = None
        self.log_screen = db.log_screen
        self.log_file = db.log_file
        self.semaphore = threading.BoundedSemaphore()
        self.running = multiprocessing.Event()

        for gnb in gnbs:
            self.gnbs.append(
                {
                    "GNB_CONFIG": gnb,
                    "EPXNS": [],
                    "SERVER": None,
                    "GNB_CONN_VARS": {
                        "num_gnb_resets": 0,
                        "num_gnb_reinits": 0,
                        "gnb_stop_timer": Timer(10),
                    },
                }
            )

        self.connect_on_start = self.db.get("CONNECT_ON_START", default=False)
        self.server_mode = self.db.get("SERVER_MODE", default=True)
        self.xn_setup_delay = self.db.get("XN_SETUP_DELAY", default=0.1)
        self.start_scn = False
        self.scn_durations = {
            "XN_SETUP": [
                random.randint(
                    self.db.get("XN_SETUP_MIN"), self.db.get("XN_SETUP_MAX")
                ),
                self.scn_XN_SETUP,
            ],
            "GNB_CONFIGURATION_UPDATE": [
                random.randint(
                    self.db.get("GNB_CONFIGURATION_UPDATE_MIN"),
                    self.db.get("GNB_CONFIGURATION_UPDATE_MAX"),
                ),
                self.scn_GNB_CONFIGURATION_UPDATE,
            ],
            "LOG_STATUS": [60, self.scn_LOG_STATUS],
        }
        self.timers = {}
        self.cfg_tasks = [
            TSK_CFG_INC_PCI,
            TSK_CFG_INC_TAC,
            # TSK_CFG_INC_GNB_ID,  # Conn reset
            # TSK_CFG_INC_MCC,     # Conn reset
            # TSK_CFG_INC_MNC,     # Conn reset
            TSK_CFG_INC_EARFCN,
            # TSK_CFG_INC_CELL_ID, # Update Failure
        ]
        self.cfg_tasks_idx = 0

    def put_task(self, task_name):
        for gnb in self.gnbs:
            epxn = self.get_dut_epxn(gnb)
            if epxn is not None:
                epxn.put_task(task_name)

    def scn_XN_SETUP(self):
        self.put_task(TSK_XN_SETUP)

    def scn_GNB_CONFIGURATION_UPDATE(self):
        if self.cfg_tasks_idx >= len(self.cfg_tasks):
            self.cfg_tasks_idx = 0
        self.put_task(self.cfg_tasks[self.cfg_tasks_idx])
        self.cfg_tasks_idx += 1
        self.put_task(TSK_GNB_CONFIGURATION_UPDATE)

    def scn_LOG_STATUS(self):
        self.log_status()

    def log_status(self):
        for gnb in self.gnbs:
            farend_ip = gnb["GNB_CONFIG"]["FAREND_IP"]
            for epxn in gnb["EPXNS"]:
                gnb_desc = epxn.desc()
                gnb_num_pending_tasks = epxn.get_num_pending_tasks()
                gnb_is_running = epxn.is_running()
                if farend_ip == epxn.farend_ip:
                    self.logfile(
                        "{}, pending({}), running=({}), reset({}), reinit({}).".format(
                            gnb_desc,
                            gnb_num_pending_tasks,
                            gnb_is_running,
                            gnb["GNB_CONN_VARS"]["num_gnb_resets"],
                            gnb["GNB_CONN_VARS"]["num_gnb_reinits"],
                        )
                    )
                else:
                    self.logfile(
                        "{}, pending({}), running=({}).".format(
                            gnb_desc, gnb_num_pending_tasks, gnb_is_running
                        )
                    )

    # Start already stopped GNB
    def reset_gnb(self, gnb):
        epxn = self.get_dut_epxn(gnb)
        if epxn is None:
            return

        # GNB has stopped - is not running
        gnb_id = epxn.gnb_id
        gnb["GNB_CONN_VARS"]["num_gnb_resets"] += 1
        if g_debug: self.log("Joining stopped GNB epxn ({})...".format(gnb_id))
        epxn.join()
        if g_debug: self.log("Joined ({}).".format(gnb_id))
        self.start_gnb(gnb)

    # Stop and Start running GNB with errors
    def reinit_gnb(self, gnb):
        epxn = self.get_dut_epxn(gnb)
        if epxn is None:
            return

        gnb_stop_timer = gnb["GNB_CONN_VARS"]["gnb_stop_timer"]
        # GNB is hung - is running and blocks sending/receiving
        if gnb_stop_timer.is_running():
            if gnb_stop_timer.check_expired():
                gnb["GNB_CONN_VARS"]["num_gnb_reinits"] += 1
                self.log("Reiniting GNB...")
                self.start_gnb(gnb)
        else:
            epxn.stop()
            gnb_stop_timer.start()

    def connect_gnbs(self):
        for gnb in self.gnbs:
            gnb_id = gnb["GNB_CONFIG"]["GNB_ID"]
            epxn = self.get_dut_epxn(gnb)
            if epxn is None:
                self.start_gnb(gnb)
                time.sleep(self.xn_setup_delay)
            elif not epxn.is_running():
                self.reset_gnb(gnb)

    def disconnect_gnb(self, gnb_id):
        for gnb in self.gnbs:
            epxn = self.get_dut_epxn(gnb)
            if epxn is None:
                continue
            if int(epxn.gnb_id) == int(gnb_id):
                epxn.stop()

    def scenario(self):
        for gnb in self.gnbs:
            epxn = self.get_dut_epxn(gnb)
            if epxn is None:
                continue
            gnb_num_pending_tasks = epxn.get_num_pending_tasks()
            if epxn.is_running():
                if gnb_num_pending_tasks >= MAX_PENDING_TASKS:
                    self.reinit_gnb(gnb)
                else:
                    self.check_timers()
            else:
                self.reset_gnb(gnb)

    def start_scenario(self):
        self.log("Starting traffic control scenario.")
        for gnb in self.gnbs:
            epxn = self.get_dut_epxn(gnb)
            if epxn is None:
                self.start_gnb(gnb)
        self.start_timers()
        self.start_scn = True

    def stop_scenario(self):
        self.log("Stopping traffic control scenario.")
        self.start_scn = False
        self.stop_timers()

    def init_timers(self):
        for scn_key in self.scn_durations.keys():
            if self.scn_durations[scn_key][0]:
                self.timers[scn_key] = Timer(
                    self.scn_durations[scn_key][0], self.scn_durations[scn_key][1]
                )

    def start_timers(self):
        for scn_key in self.timers.keys():
            self.timers[scn_key].start()

    def stop_timers(self):
        for scn_key in self.timers.keys():
            self.timers[scn_key].stop()

    def check_timers(self):
        for scn_key in self.timers.keys():
            if self.timers[scn_key].check_expired():
                self.timers[scn_key].start()

    def stop(self):
        self.running.clear()

    def is_running(self):
        return self.running.is_set()

    def loginf(self):
        return "[SCHxn-{}] ".format(self.id)

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        else:
            self.logger = Flogger(
                self.db.get_logdir() + "/LOG-EPXN-SCH-" + str(self.id) + ".log"
            )
            self.logger.write("=" * 80)
            self.logger.write("LID=[SCHEDULER]")
            msg_out = self.logger.write(msg_out)
            self.logger.flush_now()
        return msg_out

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.log_screen:
            print(msg_out)

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.mdict["errors"] += 1

    def check_log(self):
        if (
            self.mdict["log_screen"] != self.log_screen
            or self.mdict["log_file"] != self.log_file
        ):
            self.set_log(
                log_screen=self.mdict["log_screen"], log_file=self.mdict["log_file"]
            )

    def set_log(self, log_screen=True, log_file=True):
        if self.log_screen != log_screen:
            self.log_screen = log_screen
            self.set_gnb_log()
        self.log_file = log_file
        self.log("Log to screen={}, log to file={}.".format(log_screen, log_file))

    def set_gnb_log(self):
        for gnb in self.gnbs:
            for epxn in gnb["EPXNS"]:
                epxn.log_screen = self.log_screen

    def get_dut_epxn(self, gnb):
        farend_ip = gnb["GNB_CONFIG"]["FAREND_IP"]
        for epxn in gnb["EPXNS"]:
            if farend_ip == epxn.farend_ip:
                return epxn
        return None

    def dut_epxn_exists(self, gnb):
        farend_ip = gnb["GNB_CONFIG"]["FAREND_IP"]
        ret = False
        for epxn in gnb["EPXNS"]:
            if farend_ip == epxn.farend_ip and epxn.link_state == LS_CONNECTED:
                ret = True
                break
        return ret

    def start_gnb(self, gnb):
        server_stopped = False

        if self.dut_epxn_exists(gnb):
            if g_enable_prints: self.log("GNB already connected: sch_id={}, gnb={}...".format(self.id, gnb["GNB_CONFIG"]["GNB_ID"]))
            return

        if g_enable_prints: self.log("Starting scheduler id={} for gnb={}...".format(self.id, gnb["GNB_CONFIG"]["GNB_ID"]))

        if gnb["SERVER"] is not None:
            if g_enable_prints: self.log("XN Server is running. Stopping before connecting ({})...".format(gnb["GNB_CONFIG"]["GNB_ID"]))
            # gnb["SERVER"].shutdown(socket.SHUT_RD) #-> [Errno 95] Operation not supported
            gnb["SERVER"].close()
            server_stopped = True

        epxn = GNBConn(
            gnb["GNB_CONFIG"],
            gnb["GNB_CONFIG"]["IP_ADDR"],
            farend_ip=gnb["GNB_CONFIG"]["FAREND_IP"],
            xnap_config=self.db.get("XNAP"),
            logger=self.logger,
            parent_sch=self,
            log_screen=self.log_screen,
            log_file=self.log_file,
            asn_coder=asncoder.ASNCoder(protocol="XnAP"),
        )
        epxn.start()
        cnt = 0
        while cnt < 300:
            if epxn.is_running():
                epxn.put_task(TSK_XN_SETUP)
                if g_enable_prints: self.log("GNB started ({}): {}.".format(cnt, epxn.desc()))
                break
            if epxn.link_state == LS_CLOSED:
                if g_enable_prints: self.log("GNB connection closed ({}): {}.".format(cnt, epxn.desc()))
                break
            time.sleep(0.1)
            cnt += 1

        gnb["EPXNS"].append(epxn)

        if server_stopped:
            self.open_server_socket(gnb)

    def update_status(self, req=False):
        if req:
            stime = time.time()
#           if g_debug: self.log("Acquiring STAT mp_lock...")
            self.mp_lock.acquire()
        status = ""
        stat_ls_init = 0
        stat_ls_connected = 0
        stat_ls_closed = 0
        for i, gnb in enumerate(self.gnbs):
            for epxn in gnb["EPXNS"]:
                status += "  GNB({}):{}\n".format(i, epxn.desc())
                if epxn.link_state == LS_INIT:
                    stat_ls_init += 1
                elif epxn.link_state == LS_CONNECTED:
                    stat_ls_connected += 1
                elif epxn.link_state == LS_CLOSED:
                    stat_ls_closed += 1
        if not req:
            self.semaphore.acquire()
        self.mdict["status"] = status
        self.mdict["stat_ls_init"] = stat_ls_init
        self.mdict["stat_ls_connected"] = stat_ls_connected
        self.mdict["stat_ls_closed"] = stat_ls_closed
        if not req:
            self.semaphore.release()

        if req:
            self.mp_pipe.send("STAT")
            if self.mp_pipe.poll(5):
                ack = self.mp_pipe.recv_bytes()
            self.mp_lock.release()

    def open_server_sockets(self):
        for gnb in self.gnbs:
            self.open_server_socket(gnb)

    def open_server_socket(self, gnb):
        gnb["SERVER"] = None
        ip_addr = gnb["GNB_CONFIG"]["IP_ADDR"]
        gnb_id = gnb["GNB_CONFIG"]["GNB_ID"]
        try:
            sctp_sckt = socket.getprotobyname("sctp")
            if g_debug: self.log("Creating EPXN Server SCTP socket ({})...".format(gnb_id))
            server = socket.socket(xsocket.get_socket_type(ip_addr), socket.SOCK_STREAM, sctp_sckt)
            server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            if g_debug: self.log("Binding EPXN Server SCTP socket to local ip addr={} ({}).".format(ip_addr, gnb_id))
            server.bind((ip_addr, self.port))
            if g_enable_prints: self.log("EPXN Server listening on local ip addr={} ({}).".format(ip_addr, gnb_id))
            server.listen(5)
            server.settimeout(0.1)
            gnb["SERVER"] = server
        except socket.error as err:
            self.logerror(
                "Could not open epxn server socket for ip={} ({}): {}.".format(
                    ip_addr, gnb_id, err
                )
            )
            if gnb["SERVER"]:
                gnb["SERVER"].close()
                gnb["SERVER"] = None
        except Exception as exc:
            self.logerror(
                "Exception-open_server_socket for ip={} ({}) [{}]".format(
                    ip_addr, gnb_id, exc
                )
            )

    def check_server(self):
        inputs = []

        for gnb in self.gnbs:
            if gnb["SERVER"]:
                inputs.append(gnb["SERVER"])
            elif self.server_mode:
                self.open_server_socket(gnb)

            gnb_id = gnb["GNB_CONFIG"]["GNB_ID"]
            for epxn in gnb["EPXNS"][:]:
                if epxn.link_state == LS_CLOSED:
                    if g_debug: self.log("Joining closed epxn for gnb={} ({})...".format(gnb_id, epxn.desc()))
                    epxn.join()
                    if g_debug: self.log("Joined epxn for gnb={} ({})...".format(gnb_id, epxn.desc()))
                    gnb["EPXNS"].remove(epxn)

        self.update_status()

        if len(inputs) == 0:
            time.sleep(1)
            return True

        # select_timeout = 10 if self.start_scn else 30
        select_timeout = 1
        ret = True
        try:
            inputready, outputready, exceptready = select.select(
                inputs, [], [], select_timeout
            )
            if len(inputready):
                for inp in inputready:
                    for gnb in self.gnbs:
                        if inp == gnb["SERVER"]:
                            try:
                                conn, addr = inp.accept()
                                self.log(
                                    "EPXN Server: New connection to {}-{} from {}.".format(
                                        gnb["GNB_CONFIG"]["GNB_ID"],
                                        gnb["GNB_CONFIG"]["IP_ADDR"],
                                        addr,
                                    )
                                )
                                eclient = GNBConn(
                                    gnb["GNB_CONFIG"],
                                    gnb["GNB_CONFIG"]["IP_ADDR"],
                                    client=(conn, addr),
                                    logger=self.logger,
                                    parent_sch=self,
                                    log_screen=self.log_screen,
                                    log_file=self.log_file,
                                    asn_coder=asncoder.ASNCoder(protocol="XnAP"),
                                )
                                eclient.start()
                                gnb["EPXNS"].append(eclient)

                            except socket.timeout:
                                self.logerror(
                                    "EPXN Server: Socket timeout, ip={}".format(
                                        gnb["GNB_CONFIG"]["IP_ADDR"]
                                    )
                                )
                            except socket.error as err:
                                self.logerror(
                                    "EPXN Server: Socket error, ip={}: {}".format(
                                        gnb["GNB_CONFIG"]["IP_ADDR"], err
                                    )
                                )
                                ret = False
                            except Exception as exc:
                                self.logerror(
                                    "EPXN Server: Exception for incoming ip={}: {}.".format(
                                        gnb["GNB_CONFIG"]["IP_ADDR"], exc
                                    )
                                )
                                ret = False

        except select.error as exc:
            self.logerror("EPXN Server: Select error: {}.".format(exc))
            ret = False
        except Exception as exc:
            self.logerror("EPXN Server: Select Exception: {}.".format(exc))
            ret = False
        return ret

    def run(self):
        self.init_timers()
        if self.connect_on_start:
            for gnb in self.gnbs:
                self.start_gnb(gnb)
        if self.server_mode:
            self.open_server_sockets()
        self.logfile("Durations={}.".format(self.scn_durations))

        self.running.set()
        try:
            while self.running.is_set():
                self.mdict["hb"] += 1
                self.check_server()
                self.update_status()
                self.check_log()

                if self.mdict["req_stop_scn"]:
                    self.log("Stopping scenario [hb={}]".format(self.mdict["hb"]))
                    self.mdict["req_connect"] = False
                    self.mdict["req_start_scn"] = False
                    self.stop_scenario()
                    self.mdict["req_stop_scn"] = False

                if self.mdict["req_start_scn"]:
                    self.log("Starting scenario [hb={}]".format(self.mdict["hb"]))
                    self.mdict["req_connect"] = False
                    self.start_scenario()
                    self.mdict["req_start_scn"] = False

                if self.start_scn:
                    if g_debug: self.log("Processing scenario [hb={}]".format(self.mdict["hb"]))
                    self.scenario()

                if self.mdict["req_connect"]:
                    # self.log("Connecting GNBs [hb={}]".format(self.mdict["hb"]))
                    self.connect_gnbs()
                    # self.mdict["req_connect"] = False

                if self.mdict["req_disconnect"] is not None:
                    self.log("Disconnecting [hb={}]".format(self.mdict["hb"]))
                    self.disconnect_gnb(self.mdict["req_disconnect"])
                    self.mdict["req_disconnect"] = None

                if self.mdict["req_task"]:
                    self.log("Requesting task [hb={}]".format(self.mdict["hb"]))
                    task_list = self.mdict["req_task"].split("|")
                    for i, task_name in enumerate(task_list):
                        if i == len(task_list) - 1:
                            break
                        self.log("Putting task={}.".format(task_name))
                        self.put_task(task_name)
                    self.mdict["req_task"] = ""
        except Exception as exc:
            self.log(f"Exception: {exc}")
            self.log(traceback.format_exc())

        self.log("Stopping scheduler...")
        for gnb in self.gnbs:
            if gnb["SERVER"]:
                gnb["SERVER"].close()
        for gnb in self.gnbs:
            for epxn in gnb["EPXNS"]:
                epxn.stop()
                if g_debug: self.log("Joining epxn connection ({}-{})...".format(epxn.gnb_id, epxn.farend_ip))
                epxn.join()
                if g_debug: self.log("Joined epxn conn ({}-{}).".format(epxn.gnb_id, epxn.farend_ip))
        self.log("SchedulerXn stopped.")
        self.running.clear()
